from shiny import App, ui, render, reactive, Inputs, Outputs, Session

app_ui = ui.page_fluid(
    ui.layout_columns(
        # First Column: Controllers
        ui.panel_well(
            ui.input_slider("num_range", "Select Range (for numeric input):", min=0, max=100, value=(20, 80)),
            ui.input_select("color_choice", "Select Color (for dropdowns):", 
                            choices=["Red", "Green", "Blue"], selected="Red"),
            width=4
        ),
        # Second Column: Controlled Inputs
        ui.panel_well(
            ui.input_numeric("num_input", "Numeric Input (range controlled):", value=50, min=0, max=100),
            ui.input_select("color_select", "Color Select (choices controlled):", 
                           choices=["Red", "Green", "Blue"], selected="Red"),
            width=4
        ),
        # Third Column: More Inputs and Tabset
        ui.panel_well(
            ui.input_slider("slider_input", "Slider Input (range controlled):", min=0, max=100, value=50),
            ui.input_select("color_select2", "Color Select 2 (choices controlled):", 
                           choices=["Red", "Green", "Blue"], selected="Red"),
            ui.navset_tab(
                ui.nav("Tab 1", ui.output_text("tab1_output")),
                ui.nav("Tab 2", ui.output_text("tab2_output")),
            ),
            width=4
        )
    )
)

def server(input: Inputs, output: Outputs, session: Session):
    # Update numeric input range based on slider in col 1
    @reactive.effect
    def _():
        min_val, max_val = input.num_range()
        session.send_input_message("num_input", {"min": min_val, "max": max_val})
        session.send_input_message("slider_input", {"min": min_val, "max": max_val})

    # Update color choices in col 2 and 3 based on select in col 1
    @reactive.effect
    def _():
        color = input.color_choice()
        color_choices = {
            "Red": ["Red", "Pink"],
            "Green": ["Green", "Lime"],
            "Blue": ["Blue", "Cyan"]
        }
        choices = color_choices.get(color, ["Red", "Green", "Blue"])
        session.send_input_message("color_select", {"choices": choices, "selected": choices[0]})
        session.send_input_message("color_select2", {"choices": choices, "selected": choices[0]})

    @output
    @render.text
    def tab1_output():
        return f"Numeric: {input.num_input()}, Color: {input.color_select()}"

    @output
    @render.text
    def tab2_output():
        return f"Slider: {input.slider_input()}, Color2: {input.color_select2()}"

app = App(app_ui, server, debug=True)
